with flattened as (select id, service, host, latency_ms, status_code, attr_key, v from app_logs lateral view outer explode(context) x as attr_key, v) select id, service, latency_ms, status_code, attr_key, case when service rlike '^(checkout|billing)$' then 'GROUP_B' when service rlike '^(auth|search)$' then 'OTHER_ZONE' else 'CORE' end as service_zone from flattened order by id nulls first;
